/**
 * Shortfalls the presets have at every print size, under the strict reader
 * at everyday conditions, case by case.
 *
 * Generated by `pnpm verify:shortfalls --write` (tests/verify/
 * measure-shortfalls.ts): each preset with a short, a medium and a long link
 * at 40 mm, past the size where printing larger stops changing the captures,
 * all eight seeds up to every axis's everyday level. A case is an axis (or
 * the clean capture, 'baseline') where a seed failed at or before the
 * everyday level; `level` is the first level that failed (pixels a module
 * for distance), and `strict`, `zxing` and `jsqr` count how many of that
 * level's eight captures each reader read.
 *
 * The tag says whose problem it is: `decode` when the strict profile reads
 * fewer than both oracles do (it alone refuses, so it is harder than the
 * phones it stands for), `design` when jsQR misses them too (the design is
 * weak there).
 *
 * The conformance gate holds each preset to everything outside its list,
 * and calibrates its size on everything else; the nightly run fails if a
 * listed shortfall has gone, so this file cannot quietly go stale.
 */

import type { ContentSize, Shortfall } from '../../src/verify/preset.js';

export interface ShortfallCase {
	readonly preset: string;
	readonly content: ContentSize;
	readonly version: string;
	readonly axis: Shortfall;
	/** The first level that failed, in the axis's unit; pixels a module for distance. */
	readonly level: number;
	readonly seeds: number;
	readonly strict: number;
	readonly zxing: number;
	readonly jsqr: number;
	readonly tag: 'decode' | 'design';
}

