const ORDER: readonly Shortfall[] = [
	'baseline',
	'distance',
	'focus',
	'motion',
	'noise',
	'angle',
	'light',
	'glare',
	'ink',
	'contrast',
];

/** Each preset's shortfalls across its contents, in the report's order. */
export const PRESET_SHORTFALLS: Readonly<Record<string, readonly Shortfall[]>> = Object.freeze(
	SHORTFALL_CASES.reduce<Record<string, Shortfall[]>>((out, c) => {
		const list = (out[c.preset] ??= []);
		if (!list.includes(c.axis)) {
			list.push(c.axis);
			list.sort((a, b) => ORDER.indexOf(a) - ORDER.indexOf(b));
		}
		return out;
	}, {}),
);
